mapper.update:
UPDATE organization
SET path = #{path}, updated_at = NOW()
WHERE id = #{id}

UPDATE organization
SET status     = 'DELETED',
    deleted_at = #{deletedAt},
    updated_at = #{deletedAt}
WHERE id = #{id}
  AND deleted_at IS NULL

mapper.select:
SELECT COUNT(*) > 0
FROM organization
WHERE code = #{code}
